import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.CeZVUxyP.js";const u=JSON.parse('{"title":"Mission & method","description":"","frontmatter":{},"headers":[],"relativePath":"guide.md","filePath":"guide.md","lastUpdated":1794254619000}'),s={name:"guide.md"};function n(d,e,o,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="mission-method" tabindex="-1">Mission &amp; method <a class="header-anchor" href="#mission-method" aria-label="Permalink to &quot;Mission &amp; method&quot;">​</a></h1><p>Explore the limits of advanced AI across the full game creation pipeline. Our target is a small playable vertical slice, with enough evidence to explain which tools helped, which failed, and how much human work remained.</p><h2 id="principles" tabindex="-1">Principles <a class="header-anchor" href="#principles" aria-label="Permalink to &quot;Principles&quot;">​</a></h2><ul><li>Start with a constrained task and a clear acceptance test.</li><li>Preserve prompts, tool versions, settings, inputs, and output revisions.</li><li>Compare AI-assisted work with a practical manual baseline.</li><li>Record failed attempts and repair time, not just the best output.</li><li>Separate observed results from hypotheses and vendor claims.</li></ul><h2 id="shared-evaluation-dimensions" tabindex="-1">Shared evaluation dimensions <a class="header-anchor" href="#shared-evaluation-dimensions" aria-label="Permalink to &quot;Shared evaluation dimensions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>What we record</th></tr></thead><tbody><tr><td>Functional quality</td><td>Acceptance tests passed and defects discovered</td></tr><tr><td>Creative control</td><td>Ability to follow direction and reproduce style</td></tr><tr><td>Integration</td><td>Import failures, conversion work, and engine compatibility</td></tr><tr><td>Human effort</td><td>Setup, prompting, review, cleanup, and debugging minutes</td></tr><tr><td>Cost</td><td>Actual billed usage and relevant hardware costs</td></tr><tr><td>Runtime</td><td>Frame time, memory, latency, and asset size where relevant</td></tr><tr><td>Reproducibility</td><td>Version, date, inputs, seed where available, and repeat outcomes</td></tr><tr><td>Usage rights</td><td>Source terms, asset provenance, attribution, and unresolved questions</td></tr></tbody></table><h2 id="evidence-standard" tabindex="-1">Evidence standard <a class="header-anchor" href="#evidence-standard" aria-label="Permalink to &quot;Evidence standard&quot;">​</a></h2><p>A result needs an artifact or commit, a repeatable procedure, and a dated observation. A capability is <strong>untested</strong> until we run it. Use <strong>promising</strong>, <strong>blocked</strong>, or <strong>validated for this task</strong> only when evidence supports the label. A successful narrow test is not a claim of general capability.</p><h2 id="publishing-research" tabindex="-1">Publishing research <a class="header-anchor" href="#publishing-research" aria-label="Permalink to &quot;Publishing research&quot;">​</a></h2><p>Write findings as Markdown under <code>docs/</code>. Keep credentials and private inputs out of the repository. Put large source assets in appropriate asset storage and link to a versioned manifest. Record an asset&#39;s origin and usage terms before treating it as shippable.</p>',10)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
